package com.shopsphere.service; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.entity.Category; import com.shopsphere.exception.ApiException; import com.shopsphere.repository.CategoryRepository; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*; @Service public class CategoryService {private final CategoryRepository repo; public CategoryService(CategoryRepository r){repo=r;} public List<CategoryResponse> all(){return repo.findAll().stream().map(c->new CategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription())).toList();} public CategoryResponse create(CategoryRequest r){Category c=new Category();c.setName(r.name());c.setSlug(r.slug());c.setDescription(r.description());repo.save(c);return new CategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription());} }